<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; class CheckoutTaxLine extends Model { protected $fillable=['checkout_session_id','checkout_session_item_id','vendor_id','tax_jurisdiction_id','tax_class_id','tax_rate_id','source','source_reference','label','rate_bps','taxable_minor','tax_minor','price_includes_tax','liability_bearer','metadata']; protected function casts():array{return ['rate_bps'=>'integer','taxable_minor'=>'integer','tax_minor'=>'integer','price_includes_tax'=>'boolean','metadata'=>'array'];} public function checkoutSession(){return $this->belongsTo(CheckoutSession::class);} public function checkoutItem(){return $this->belongsTo(CheckoutSessionItem::class,'checkout_session_item_id');} public function jurisdiction(){return $this->belongsTo(TaxJurisdiction::class,'tax_jurisdiction_id');} public function taxClass(){return $this->belongsTo(TaxClass::class);} public function rate(){return $this->belongsTo(TaxRate::class,'tax_rate_id');} }